            <input v-model="search" placeholder="Cerca piloti, compagni o utenti…" aria-label="Cerca persone" />
            <button v-if="search" aria-label="Cancella ricerca" @click="search = ''">×</button>
          </label>

          <div v-if="search" class="pwc-search-results">
            <h2>Nelle tue Crew</h2>
            <article v-for="person in searchResults.known" :key="person.id" class="pwc-person-row">
              <span class="pwc-avatar" :class="`is-${person.source}`">{{ person.initials }}</span>
              <div><strong>{{ person.name }}</strong><small>{{ person.detail }}</small></div>
              <span class="pwc-state" :class="`is-${person.state}`">{{ person.state === 'racing' ? 'In gara' : 'Disponibile' }}</span>
              <button v-if="person.state === 'racing'" class="pwc-btn is-primary" @click="go('live')">Assisti</button>
            </article>
            <h2>Altri utenti</h2>
            <article v-for="person in searchResults.global" :key="person.id" class="pwc-person-row">
              <span class="pwc-avatar is-global">{{ person.initials }}</span>
              <div><strong>{{ person.name }}</strong><small>{{ person.detail }}</small></div>
              <button class="pwc-btn is-outline">{{ person.id === 'martina' ? 'Chiedi accesso' : 'Invita in una Crew' }}</button>
            </article>
            <p v-if="!searchResults.known.length && !searchResults.global.length" class="pwc-empty">Nessun risultato. Prova con nome o nickname.</p>
          </div>

          <template v-else>
            <h2 class="pwc-section-title">Adesso <span></span><small>2</small></h2>
