              <article class="pwc-driver-card is-crew">
                <span class="pwc-live-dot"></span><span class="pwc-avatar">MR</span>
                <div><strong>Mario Rossi</strong><small class="pwc-tag is-green">Crew</small></div>
                <div><strong>Ferrari 296 GT3</strong><small>Monza</small></div><div><strong>P7</strong><small>Posizione</small></div><div><strong>Giro 18</strong><small>32 minuti fa</small></div>
                <button class="pwc-btn is-primary" @click="go('live')">Assisti</button>
              </article>
              <article class="pwc-driver-card is-guest">
                <span class="pwc-live-dot is-violet"></span><span class="pwc-avatar is-guest">AV</span>
                <div><strong>Andrea Verdi</strong><small class="pwc-tag is-violet">Ospite</small></div>
                <div><strong>McLaren 720S GT3</strong><small>Spa</small></div><div><strong>P12</strong><small>Posizione</small></div><div><strong>Giro 9</strong><small>Accesso fino a fine gara</small></div>
                <button class="pwc-btn is-primary" @click="go('live')">Assisti</button>
              </article>
            </div>
