mall></div><button class="pwc-btn" :class="{ 'is-added': invitees.includes(person.id) }" @click="toggleInvitee(person.id)" > {{ invitees.includes(person.id) ? "Aggiunto" : "Aggiungi" }} </button></article></section><aside><h3>Invitati · {{ invitees.length }}</h3><article v-for="id in invitees" :key="id"><strong>{{ PITWALL_CONCEPT_PEOPLE.find((item) => item.id === id)?.name }}</strong ><button @click="toggleInvitee(id)">Rimuovi</button></article></aside><footer><button class="pwc-btn" @click="go('crew-create-identity')"> Indietro</button ><button class="pwc-btn" @click="go('crew-detail')">Salta</button ><button class="pwc-btn is-primary" @click="go('crew-detail')"> Crea e invita </button></footer></div></div></template><template v-else-if="screen === 'crew-detail'"><div class="pwc-crew-page"><button class="pwc-back" @click="go('home')">← Le mie Crew</button><header><div><h1>{{ crewName || "Apex One Racing" }}</h1><p>{{ crewDescription }}</p></div><div><span>4 membri</span ><button class="pwc-btn is-outline">+ Invita</button ><button class="pwc-btn">Impostazioni</button></div></header><div class="pwc-crew-grid"><main><h2>Attività della Crew</h2><article class="pwc-race-card"><header><span class="pwc-tag is-green">Live</span><h3>Ferrari 296 GT3 · Monza</h3><small>Endurance</small></header><div class="pwc-race-stats"><div><b>P7</b><small>Posizione</small></div><div><b>18 / 42</b><small>Giro</small></div><div><b>31 min</b><small>Stint attuale</small></div><div><b>24–27</b><small>Pit window</small></div></div><div class="pwc-race-people"><p><span>◉</span><b>Mario Rossi</b><small>Al volante</small ><button class="pwc-btn" @click="go('live')">Assisti</button></p><p><span>○</span><b>Luca Bianchi</b><small>Disponibile</small></p><p><span>◉</span><b>Enrico Saiani</b ><small>Sta assistendo</small></p></div></article><h2>Attività recenti</h2><article class="pwc-recent"><b>Luca</b><span>Spa</span><span>terminata 1 ora fa</span ><button class="pwc-btn">Riepilogo</button></article>