urante</span><div class="pwc-step"><button @click="strategy.fuel = Math.max(0, strategy.fuel - 1)"> −</button ><b>{{ strategy.fuel }} L</b ><button @click="strategy.fuel++">+</button></div><b>0 L</b></div><div class="pwc-pit-row"><span>Cambio gomme</span ><label ><input v-model="strategy.tyres" type="checkbox" /> {{ strategy.tyres ? "Sì" : "No" }}</label ><b>No</b></div><div class="pwc-pit-row"><span>Set pneumatici</span><div class="pwc-step"><button @click="strategy.tyreSet = Math.max(1, strategy.tyreSet - 1)" > −</button ><b>{{ strategy.tyreSet }}</b ><button @click="strategy.tyreSet++">+</button></div><b>1</b></div><div class="pwc-pit-row"><span>Mescola</span ><select v-model="strategy.compound"><option>Dry</option><option>Wet</option></select ><b>Dry</b></div><div class="pwc-pit-row"><span>Pressioni</span><div class="pwc-step"><button @click="stepAll(-1)">−</button><b>Tutte</b ><button @click="stepAll(1)">+</button></div><b>—</b></div><div v-for="wheel in ['FL', 'FR', 'RL', 'RR'] as const" :key="wheel" class="pwc-pit-row is-sub" ><span>{{ wheel }}</span><div class="pwc-step"><button @click="stepPressure(wheel, -1)">−</button ><b>{{ pressures[wheel].toFixed(1) }}</b ><button @click="stepPressure(wheel, 1)">+</button></div><b>25.0</b></div><div class="pwc-pit-row"><span>Sostituisci freni</span ><label ><input v-model="strategy.brakes" type="checkbox" /> {{ strategy.brakes ? "Sì" : "No" }}</label ><b>No</b></div><div class="pwc-pit-row"><span>Prossimo pilota</span ><select v-model="strategy.driver"><option>Nessun cambio</option><option>Luca Bianchi</option></select ><b>Nessun cambio</b></div><div class="pwc-pit-row"><span>Sospensioni</span ><label ><input v-model="strategy.suspension" type="checkbox" /> {{ strategy.suspension ? "Sì" : "No" }}</label ><b>No</b></div><div class="pwc-pit-row"><span>Carrozzeria</span ><label ><input v-model="strategy.bodywork" type="checkbox" /> {{ strategy.bodywork ? "Sì" : "No" }}</label ><b>No</b></div><div class="pwc-pit-row"><span